/* Generated by scripts/new-video.mjs for videos/ngantuk-pegang-hp: the checks a new video passes before it is handed back (DESIGN.md section 0b). Add
   "node tests/ngantuk-pegang-hp.test.ts" to the test script in package.json so `npm test` runs it. It reads the story and the plan, and runs the checker. */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { makePlan } from "../videos/ngantuk-pegang-hp/plan.ts";
import { sfx } from "../videos/ngantuk-pegang-hp/sfx.ts";
import { validateStory } from "../src/schema.ts";
import { FPS } from "../src/timeline.ts";
import { MAX_SIMULTANEOUS_SFX, SFX } from "../src/catalog.ts";
import { textWidthEstimate } from "../src/layout.ts";

let n = 0;
const yes = (c: boolean, what: string) => { n++; assert.ok(c, what); };
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.join(ROOT, "videos", "ngantuk-pegang-hp");
const raw = JSON.parse(readFileSync(path.join(dir, "story.json"), "utf8"));
const v = validateStory(raw);
yes(v.ok, `the story of videos/ngantuk-pegang-hp is valid${v.ok ? "" : `: ${v.errors.join("; ")}`}`);
if (!v.ok) { console.log(`ngantuk-pegang-hp: ${n} checks ok (the story is not valid)`); process.exit(1); }
const story = v.story;

// the timing: the sting right after the hook, the loop-back last, the plan's times are the beats'
const P = makePlan(story);
yes(P.total === story.duration, "the plan's total is the story's duration");
yes(P.m.sting === story.beats[0].dur, "the sting starts where the hook ends (must 1)");
yes(story.beats.at(-1)?.kind === "outro" && P.m.outro === P.total - story.beats.at(-1)!.dur, "the outro starts at the last beat (must 2)");
yes(P.loopWeight(P.m.outro) === 0 && P.loopWeight(P.total) === 1, "the loop weight runs from 0 at the outro to 1 at the end");

// the checker: no FAIL (the musts and the motion language); its flags are read in the report, not hidden
const check = spawnSync(process.execPath, [path.join(ROOT, "scripts", "styleCheck.mjs"), "ngantuk-pegang-hp"], { encoding: "utf8" });
yes(!/^FAIL/m.test(check.stdout), `the checker has no FAIL line:\n${check.stdout.split("\n").filter((l) => /^FAIL/.test(l)).join("\n")}`);

// every frame's boxes pass the layout manager (labels, tip cards, the bed, the sting, the top text, the captions)
const wrapN = (text: string, fs: number, width: number) => { let lines = 0, cur = ""; for (const w of text.split(/\s+/)) { if (cur && textWidthEstimate(`${cur} ${w}`, fs) > width) { lines++; cur = w; } else cur = cur ? `${cur} ${w}` : w; } return lines + (cur ? 1 : 0); };
const tipH = (i: number) => { const tp = P.tips[i]; return 48 + wrapN(tp.title, 58, P.TIP.w - 170) * 66 + (tp.sub ? wrapN(tp.sub, 40, P.TIP.w - 170) * 50 + 8 : 0) + 30; };
const bad: string[] = [];
for (let f = 0; f < P.total * FPS; f += 3) { const t = f / FPS, pr = P.problemsAt(t, tipH); if (pr.length) bad.push(`${t.toFixed(2)}s: ${pr.join("; ")}`); }
yes(bad.length === 0, `no overlap or safe-area problem on any third frame (${bad.slice(0, 4).join(" | ")})`);

// the words on the screen are the story's (bar the channel's chrome); the story's HP placeholder is not drawn as text, the object is drawn
const hay = story.beats.flatMap((b) => [b.narration, b.text, ...b.scene.items.flatMap((i) => ("text" in i ? [i.text] : []))]).join(" ").toLowerCase();
yes(P.labels.length >= 10 && P.labels.every((l) => hay.includes(l.text.toLowerCase())), "every label's text is a text of the story");
yes(P.labels.every((l) => l.text !== "HP"), "no label says HP: the phone is drawn");
yes(P.tips.length === 2 && P.tips.every((tp) => hay.includes(tp.title.toLowerCase())), "the two tip cards carry the story's tip texts");

// the camera never jumps
let worst = 0;
for (let f = 1; f < P.total * FPS; f++) { const a = P.outCam((f - 1) / FPS), b = P.outCam(f / FPS); worst = Math.max(worst, Math.hypot(b.x - a.x, b.y - a.y) * Math.min(a.zoom, b.zoom), Math.abs(Math.log(b.zoom / a.zoom)) * 1000); }
yes(worst < 60, `the camera moves smoothly (worst step ${worst.toFixed(1)} px per frame)`);

// the loop: the camera and every state come home, so the last frame is the first one's (the render's seam test gives the numbers)
const last = P.total - 1 / FPS, c0 = P.outCam(0), c1 = P.outCam(last), s0 = P.state(0), s1 = P.state(last);
yes(Math.hypot(c1.x - c0.x, c1.y - c0.y) < 1 && Math.abs(c1.zoom - c0.zoom) < 0.005, "the camera of the last frame is the opening shot's");
yes(Object.keys(s0).every((k) => Math.abs((s1 as Record<string, number>)[k] - (s0 as Record<string, number>)[k]) < 1e-6), "every state of the last frame equals the first frame's (phone, lids, brows, bubble, trip)");
yes(s0.bubble === 0 && s0.away === 0 && s0.on === 1, "the opening shot: a lit phone on the bed, no bubble");
yes(!P.labels.some((l) => l.to > P.m.outro) && !P.tops.some((x) => x.b > P.m.outro) && !P.tips.some((x) => x.to > P.m.outro) && !P.steps.some((x) => x.to > P.m.outro), "no text, label, step or card reaches into the outro");
yes(P.m.react >= P.m.sting + 1 && P.m.react + 1.25 < P.m.outro, "the one reaction is between the sting and the outro, and short");

// the story the picture tells: droopy lids while the phone is in hand, wide open when it is put down, the phone leaves in tip 1
yes(P.state(P.m.lie - 0.1).open > 0.9 && P.state(P.beat("baring").b - 0.1).open < 0.35, "the lids go from open to heavy through the lying down");
yes(P.state(P.m.putDown + 1).open > 0.95 && P.state(P.m.putDown - 0.2).open < 0.65, "the lids open wide when the phone is put down");
yes(P.state(P.m.putDown + 1).on < 0.2 && P.state(P.beat("layar").a + 2).on > 0.95, "the screen is lit while it is in hand and dark once it is put down");
yes(P.state(P.m.away + 2).away > 0.95 && P.state(P.m.tip2 - 0.1).bubble > 0.5, "the phone has left by tip 2 and the bubble is still there");

// depth order (read from the picture's source): the bed, the beam, the phone, the eyes, then the bubble
const src = readFileSync(path.join(dir, "index.tsx"), "utf8");
const at = (needle: string) => src.indexOf(needle);
yes(at("<IsoBed") < at("<polygon points={beam") && at("<polygon points={beam") < at("<IsoPhone") && at("<IsoPhone") < at("<SleepyEyes") && at("<SleepyEyes") < at("<Thought"), "depth order: bed, light beam, phone, eyes, thought bubble");

// the sound: every event on a frame, inside the video, at most three at once, only names of the approved set, no jingle in the loop-back
const ev = sfx(story);
yes(ev.every((e) => Math.abs(e.t * FPS - Math.round(e.t * FPS)) < 1e-6 && e.t < P.total), "every sound on a frame, inside the video");
yes(ev.every((e) => e.name in SFX), "every sound is of the approved set");
let most = 0;
for (let f = 0; f < P.total * FPS; f++) { const t = f / FPS; most = Math.max(most, ev.filter((e) => t >= e.t && t < e.t + SFX[e.name].dur && !("loop" in SFX[e.name]) && !("bed" in SFX[e.name])).length); }
yes(most <= MAX_SIMULTANEOUS_SFX + 1, `at most ${MAX_SIMULTANEOUS_SFX} one-shots sound at once before the mixer's cooldowns (${most} at worst)`);
yes(!ev.some((e) => e.name === "jingle-outro" || (e.t >= P.m.outro && e.name === "boing")), "the loop-back has no jingle and no mascot sound");
yes(ev.length >= 30 && ev.length <= 52, `the sound density is near the approved mix (${ev.length} events in ${P.total} s)`);

console.log(`ngantuk-pegang-hp: ${n} checks ok`);
